(async()=>{const s=ms=>new Promise(r=>setTimeout(r,ms)); const out=[];
document.querySelector('[data-go="vocabulario/v-food"]')||0; location.hash='vocabulario/v-food'; await s(800);
document.querySelector('#gFlash').click(); await s(1500);
const setMode=async m=>{ document.querySelector('[data-fmode="'+m+'"]').click(); await s(300); };
await setMode('en-es');
// 1: respuesta correcta (sin tildes) usando el significado real
for(let k=0;k<3;k++){
  const w=document.querySelector('.face .fw').childNodes[0].textContent.trim();
  const es=document.querySelector('.face.back b').textContent;
  const val = k===0 ? es.split('/')[0].normalize('NFD').replace(/[\u0300-\u036f]/g,'') : k===1 ? 'xyz' : '';
  const inp=document.querySelector('#fans'); inp.value=val;
  if(k===2) document.querySelector('#idk').click(); else inp.dispatchEvent(new KeyboardEvent('keydown',{key:'Enter',bubbles:true}));
  await s(300);
  out.push(w+' ['+val+'] → '+document.querySelector('#fres').innerText+' | botones: '+[...document.querySelectorAll('#frow button')].map(b=>b.innerText).join(', ')+' | flip='+document.querySelector('#card').classList.contains('flip'));
  if(k===0) window.__shot=1;
  if(k===1){ document.querySelector('#valid').click(); } else document.querySelector('#nxt').click();
  await s(400);
}
await setMode('es-en');
const es=document.querySelector('.face .fw').innerText; const en=document.querySelector('.face.back .fw').innerText;
const inp=document.querySelector('#fans'); inp.value=en; document.querySelector('#chk').click(); await s(300);
out.push('ES→EN '+es+' ['+en+'] → '+document.querySelector('#fres').innerText);
return out.join('\n');})()

(async()=>{
const sleep=ms=>new Promise(r=>setTimeout(r,ms)); const log=[];
document.querySelector('[data-act="reto"]').click(); await sleep(400);
for(let n=0;n<40;n++){
  if(document.querySelector('.result')) break;
  const label=document.querySelector('.qtype span')?.textContent; const card=document.querySelector('.qcard');
  let kind='?';
  if(card.querySelector('.match')){ kind='match';
    for(const L of [...card.querySelectorAll('[data-l]')]){ L.click(); for(const R of [...card.querySelectorAll('[data-r]:not(.gone):not(.right)')]){ R.click(); await sleep(30); if(L.classList.contains('right')) break; } await sleep(300); } }
  else if(card.querySelector('#tPool')){ kind='order'; let g=0; while(card.querySelector('[data-p]') && g++<30){ card.querySelector('[data-p]').click(); } document.querySelector('#check').click(); }
  else if(card.querySelector('#ans')){ kind='type'; card.querySelector('#ans').value= n%2? 'test':''; document.querySelector('#check').click(); }
  else if(card.querySelector('[data-t]')){ kind='err'; card.querySelector('[data-t]').click(); }
  else if(card.querySelector('[data-o]')){ kind='mc'; card.querySelector('[data-o]').click(); }
  await sleep(150);
  const fb=document.querySelector('#fb').textContent.trim().slice(0,70);
  log.push(n+1+' '+kind+' | '+label+' | '+fb);
  const nx=document.querySelector('#next'); if(!nx || nx.classList.contains('hidden')){ log.push('  !! no next button'); break; }
  nx.click(); await sleep(150);
}
log.push('RESULT: '+(document.querySelector('.result h1')?.textContent||'no result'));
return log.join('\n');
})()
